import { mapState } from 'vuex';
import { pluralize } from 'optinmonster-js-library/src/utils/strings';

export const bulk = {
	computed: {
		...mapState('campaigns', ['bulk']),
		campaignPlural() {
			return this.makePlural('campaign');
		},
		contactPlural() {
			return this.makePlural('contact');
		},
		count() {
			return this.bulk.length;
		},
	},
	methods: {
		makePlural(string) {
			return pluralize(string, this.bulk.length);
		},
	},
};
